// Illustration resolver. Real photos always win: ProductImage shows the uploaded image when the product has one, and only
// falls back to these SVGs (apps/web/public/assets, generated by tools/art/gen_art.py). To use your own photos, upload them
// on the product (seller panel) or drop files with the same names into public/assets/products/ and change the extension below.
const ASSET_EXT = 'svg';

const norm = (s: string) => s.toLowerCase().replace(/[ʻʼ‘’`']/g, '').replace(/\s+/g, ' ').trim();

// Order matters: first match wins.
const PRODUCT_RULES: Array<[RegExp, string]> = [
  [/kartoshka/, 'kartoshka'], [/piyoz/, 'piyoz'], [/sabzi/, 'sabzi'], [/pomidor/, 'pomidor'], [/bodring/, 'bodring'], [/olma|nok |behi/, 'olma'],
  [/tovuq|parranda|broyler|kurka/, 'tovuq-goshti'], [/mol |qoy|goshti|gosht|kabob|qiyma/, 'mol-goshti'], [/tuxum/, 'tuxum'],
  [/sut|qatiq|qaymoq|kefir|smetana/, 'sut'], [/^un |^un$|bugdoy|\bun\b/, 'un'], [/guruch|grechka|yorma|manka|nohat|mosh|loviya|dukkak/, 'guruch'],
  [/yog$|\byog\b|moy|zaytun/, 'yog'], [/shakar|qand|tuz/, 'shakar'], [/non|patir|lavash|bulochka|somsa/, 'non'],
];
// Category names/slugs (first level and sub-level) → category art.
const CATEGORY_RULES: Array<[RegExp, string]> = [
  [/sabzavot|kartoshka|pomidor|kokat/, 'sabzavotlar'], [/meva|sitrus|quruq/, 'mevalar'], [/gosht|parranda|tovuq|tuxum/, 'gosht-va-parranda'],
  [/sut|qatiq|pishloq/, 'sut-mahsulotlari'], [/non|^un|makaron/, 'non-va-un'], [/don|yorma|guruch|grechka|dukkak/, 'don-va-yormalar'],
  [/yog|ziravor|tuz|shakar/, 'yog-va-ziravorlar'], [/ichimlik|suv|choy|qahva|sharbat/, 'ichimliklar'], [/uy-rozgor|uy rozgor|tozalash|gigiyena/, 'uy-rozgor'],
];

export function productArt(name: string, category?: string | null): string {
  const n = norm(name) + ' ';
  for (const [re, f] of PRODUCT_RULES) if (re.test(n)) return `/assets/products/${f}.${ASSET_EXT}`;
  return categoryArt(category);
}
export function categoryArt(category?: string | null): string {
  const c = norm(category ?? '').replace(/\s+/g, '-');
  for (const [re, f] of CATEGORY_RULES) if (re.test(c) || re.test(norm(category ?? ''))) return `/assets/categories/${f}.${ASSET_EXT}`;
  return `/assets/categories/default.${ASSET_EXT}`;
}
